To solve this task, we need to create a Python script that validates the specified pipeline outputs and generates a JSON summary of the validation checks. The script should perform several checks on each of the listed output files and report the results in a structured JSON format.

Here is the solution:

<solution_file path="src/validate_outputs.py">
import json
import os
import pandas as pd

def validate_file_exists(file_path):
    if not os.path.exists(file_path):
        return False, f"File not found: {file_path}"
    return True, None

def validate_file_not_empty(file_path):
    if os.path.getsize(file_path) == 0:
        return False, f"File is empty: {file_path}"
    return True, None

def validate_csv_columns(file_path, expected_columns):
    try:
        df = pd.read_csv(file_path)
        if list(df.columns) != expected_columns:
            return False, f"Columns do not match expected: {file_path}"
        return True, None
    except Exception as e:
        return False, f"Error reading CSV file: {file_path}. Error: {str(e)}"

def validate_json_keys(file_path, expected_keys):
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
            if set(data.keys()) != set(expected_keys):
                return False, f"Keys do not match expected: {file_path}"
        return True, None
    except Exception as e:
        return False, f"Error reading JSON file: {file_path}. Error: {str(e)}"

def run_validation_checks():
    validation_results = []

    # Check for outputs/t01_selected_indicators.csv
    file_path = "outputs/t01_selected_indicators.csv"
    exists, message = validate_file_exists(file_path)
    validation_results.append({
        "check_name": f"File exists: {file_path}",
        "passed": exists,
        "message": message
    })

    if exists:
        not_empty, message = validate_file_not_empty(file_path)
        validation_results.append({
            "check_name": f"File not empty: {file_path}",
            "passed": not_empty,
            "message": message
        })

        if not_empty:
            expected_columns = ['indicator_id', 'indicator_name', 'theme', 'justification', 'expected_direction']
            columns_match, message = validate_csv_columns(file_path, expected_columns)
            validation_results.append({
                "check_name": f"Columns match expected: {file_path}",
                "passed": columns_match,
                "message": message
            })

    # Check for outputs/t05_clean_stops.csv
    file_path = "outputs/t05_clean_stops.csv"
    exists, message = validate_file_exists(file_path)
    validation_results.append({
        "check_name": f"File exists: {file_path}",
        "passed": exists,
        "message": message
    })

    if exists:
        not_empty, message = validate_file_not_empty(file_path)
        validation_results.append({
            "check_name": f"File not empty: {file_path}",
            "passed": not_empty,
            "message": message
        })

        if not_empty:
            expected_columns = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']
            columns_match, message = validate_csv_columns(file_path, expected_columns)
            validation_results.append({
                "check_name": f"Columns match expected: {file_path}",
                "passed": columns_match,
                "message": message
            })

    # Check for outputs/t08_pois_clean.csv
    file_path = "outputs/t08_pois_clean.csv"
    exists, message = validate_file_exists(file_path)
    validation_results.append({
        "check_name": f"File exists: {file_path}",
        "passed": exists,
        "message": message
    })

    if exists:
        not_empty, message = validate_file_not_empty(file_path)
        validation_results.append({
            "check_name": f"File not empty: {file_path}",
            "passed": not_empty,
            "message": message
        })

        if not_empty:
            expected_columns = ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']
            columns_match, message = validate_csv_columns(file_path, expected_columns)
            validation_results.append({
                "check_name": f"Columns match expected: {file_path}",
                "passed": columns_match,
                "message": message
            })

    # Check for outputs/t10_accessibility_scores.csv
    file_path = "outputs/t10_accessibility_scores.csv"
    exists, message = validate_file_exists(file_path)
    validation_results.append({
        "check_name": f"File exists: {file_path}",
        "passed": exists,
        "message": message
    })

    if exists:
        not_empty, message = validate_file_not_empty(file_path)
        validation_results.append({
            "check_name": f"File not empty: {file_path}",
            "passed": not_empty,
            "message": message
        })

        if not_empty:
            expected_columns = ['qid', 'label', 'poi_type', 'distance_m', 'n_departures', 'n_routes', 'accessibility_score']
            columns_match, message = validate_csv_columns(file_path, expected_columns)
            validation_results.append({
                "check_name": f"Columns match expected: {file_path}",
                "passed": columns_match,
                "message": message
            })

    # Check for outputs/t13_city_clusters.csv
    file_path = "outputs/t13_city_clusters.csv"
    exists, message = validate_file_exists(file_path)
    validation_results.append({
        "check_name": f"File exists: {file_path}",
        "passed": exists,
        "message": message
    })

    if exists:
        not_empty, message = validate_file_not_empty(file_path)
        validation_results.append({
            "check_name": f"File not empty: {file_path}",
            "passed": not_empty,
            "message": message
        })

    # Write the validation results to JSON file
    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(validation_results, f, indent=2)

if __name__ == "__main__":
    run_validation_checks()
